-- P2 家庭数字资产（PostgreSQL 17）
CREATE TABLE IF NOT EXISTS "family_document" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"space_id" bigint NOT NULL,"owner_id" bigint NOT NULL,"file_id" bigint NOT NULL,"title" varchar(255) NOT NULL,"category" varchar(40) NOT NULL DEFAULT 'OTHER',"tags" varchar(1000),"extracted_text" text,"version_no" int NOT NULL DEFAULT 1,"status" varchar(20) NOT NULL DEFAULT 'READY',"error_message" varchar(2000),"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,"update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,"deleted" smallint NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS "family_document_search" ON "family_document" ("space_id","category","status","deleted","update_time");
CREATE TABLE IF NOT EXISTS "family_document_version" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"document_id" bigint NOT NULL,"file_id" bigint NOT NULL,"version_no" int NOT NULL,"change_note" varchar(500),"created_by" bigint NOT NULL,"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "family_document_version_uk" ON "family_document_version" ("document_id","version_no");
CREATE TABLE IF NOT EXISTS "photo_duplicate_candidate" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"space_id" bigint NOT NULL,"media_id" bigint NOT NULL,"duplicate_media_id" bigint NOT NULL,"match_type" varchar(20) NOT NULL,"confidence" numeric(6,5) NOT NULL DEFAULT 1,"marked" smallint NOT NULL DEFAULT 1,"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "photo_duplicate_pair_uk" ON "photo_duplicate_candidate" ("media_id","duplicate_media_id");
CREATE TABLE IF NOT EXISTS "family_share_link" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"space_id" bigint NOT NULL,"created_by" bigint NOT NULL,"resource_type" varchar(30) NOT NULL,"resource_id" bigint,"token" varchar(80) NOT NULL,"expires_at" timestamp,"status" smallint NOT NULL DEFAULT 1,"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "family_share_token_uk" ON "family_share_link" ("token");
CREATE TABLE IF NOT EXISTS "family_device" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"space_id" bigint NOT NULL,"user_id" bigint NOT NULL,"device_name" varchar(100) NOT NULL,"device_type" varchar(30) NOT NULL,"device_key" varchar(120) NOT NULL,"sync_cursor" varchar(120),"last_seen_at" timestamp,"status" smallint NOT NULL DEFAULT 1,"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,"update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "family_device_key_uk" ON "family_device" ("device_key");
CREATE TABLE IF NOT EXISTS "family_sync_log" ("id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"device_id" bigint NOT NULL,"direction" varchar(20) NOT NULL,"entity_type" varchar(40) NOT NULL,"entity_id" bigint,"operation" varchar(20) NOT NULL,"conflict_status" varchar(20) NOT NULL DEFAULT 'NONE',"message" varchar(2000),"create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "family_sync_device_time" ON "family_sync_log" ("device_id","create_time");
INSERT INTO "sys_menu" ("parent_id","name","path","component","type","permission","icon","sort","status","create_time","update_time") SELECT 0,'家庭资产','/family-assets','family-assets/index',1,'family:asset:list','FolderOpened',5,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM "sys_menu" WHERE "path"='/family-assets');
INSERT INTO "sys_role_menu" ("role_id","menu_id") SELECT 1,m.id FROM "sys_menu" m WHERE m.path='/family-assets' AND NOT EXISTS (SELECT 1 FROM "sys_role_menu" rm WHERE rm.role_id=1 AND rm.menu_id=m.id);
